            </DrawerDescription>
          </div>
          <DrawerClose asChild>
            <Button aria-label="Close" size="icon-sm" variant="ghost">
              <CloseIcon />
            </Button>
          </DrawerClose>
        </DrawerHeader>

        {/* Keyed on open, so every opening loads afresh — and the failure
            case fails every time until Try again. */}
        {open ? (
          <HistoryBody
            approval={approval}
            canEdit={canEdit}
            caseId={caseId}
            editing={editing}
            initial={initial}
