  children: React.ReactNode
}) {
  const hidden = new Set(hiddenItems ?? [])
  const groups = NAV.map((group) => ({
    ...group,
    items: group.items
      .flatMap((item) => [
        item,
        ...(addedItems ?? [])
          .filter((added) => added.after === item.title)
          .map((added) => added.item),
      ])
      .filter((item) => !hidden.has(item.title)),
  })).filter((group) => group.items.length > 0)

  return (
    // The app's sidebar is 15rem; shadcn ships 16rem. Set here because the primitive is generated.
    <SidebarProvider
      className="min-h-0 flex-1"
      style={{ "--sidebar-width": "15rem" } as React.CSSProperties}
    >
      {/* Starts below the mockup shell's 48px bar. */}
      <Sidebar
        className={underShell ? "pt-12" : undefined}
        collapsible="icon"
        variant="inset"
      >
        <SidebarHeader className="px-2 pt-2 pb-1">
          <div className="flex items-center justify-between group-data-[state=collapsed]:justify-center">
            {/* 56×32 is the size the app's own header renders it at. */}
            <Image
              alt="sarj.ai"
              className="group-data-[state=collapsed]:hidden"
              height={32}
              priority
              src="/logo.png"
              width={56}
            />
            <SidebarTrigger className="size-8 rounded-md text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-5" />
          </div>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup className="pt-2 pb-0">
            <SidebarGroupContent>
              <SidebarMenu>
                <NavLink
                  active={PLAYGROUND.title === active}
                  item={PLAYGROUND}
                  onNavigate={onNavigate}
                />
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          {groups.map((group, index) => (
            <React.Fragment key={group.label}>
              {index > 0 ? (
                <div className="mx-2 my-1 hidden h-px shrink-0 bg-sidebar-border group-data-[collapsible=icon]:block" />
              ) : null}
              <NavGroup
                active={active}
                defaultOpen={
                  group.defaultOpen ||
                  group.items.some((item) => item.title === active)
                }
                items={group.items}
                label={group.label}
                onNavigate={onNavigate}
              />
            </React.Fragment>
          ))}
        </SidebarContent>
      </Sidebar>

      <SidebarInset className="min-w-0 overflow-hidden">
        <AppHeader
          developers={developers}
          scope={scope}
          trail={
            breadcrumb === undefined
              ? [active]
              : typeof breadcrumb === "string"
                ? [breadcrumb]
                : breadcrumb
          }
          showSettings={!hidden.has("Global Settings")}
        />
        <div className="min-h-0 flex-1 overflow-auto">{children}</div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import * as React from "react"
import Link from "next/link"

import { Button } from "@/components/ui/button"
import { BackIcon } from "@/components/shell/workspace-icons"

/** 48px tall: `AppShell` starts its fixed sidebar under it. */
export function MockupShell({
  title,
  actions,
  children,
}: {
  title: string
  /** Kept for the callers that pass it; the bar shows the title alone. */
  eyebrow?: string
  actions?: React.ReactNode
  children: React.ReactNode
}) {
  return (
    <div className="flex min-h-full grow flex-col bg-sidebar">
      <header className="sticky top-0 z-nav flex h-12 shrink-0 items-center gap-2 border-b bg-sidebar px-3">
        <Button aria-label="All mockups" asChild size="icon-sm" variant="ghost">
          <Link href="/">
            <BackIcon />
          </Link>
        </Button>
        <span
          className="min-w-0 flex-1 truncate text-sm font-medium"
          title={title}
        >
          {title}
        </span>
        {actions ? (
          <div className="flex shrink-0 items-center gap-1.5">{actions}</div>
        ) : null}
      </header>

      <div className="flex min-h-0 flex-1 flex-col">{children}</div>
    </div>
  )
}

